BEGIN;
DROP FUNCTION IF EXISTS refs_complete_wbs_autorec_reverse(uuid,uuid,uuid,text,text,text);
DROP FUNCTION IF EXISTS refs_create_wbs_autorec_reverse_draft(uuid,uuid,uuid,text,uuid,uuid,text,text,text);
DROP FUNCTION IF EXISTS refs_request_wbs_autorec_reverse(uuid,uuid,uuid,text,text,text);
DROP FUNCTION IF EXISTS refs_wbs_autorec_reverse_draft_hash(uuid,uuid,uuid,text,uuid,uuid,text);
DROP FUNCTION IF EXISTS refs_wbs_autorec_reverse_request_hash(uuid,uuid,uuid,text);
DROP TRIGGER IF EXISTS wbs_autorec_reversal_je_guard ON journal_entry;
DROP FUNCTION IF EXISTS refs_validate_wbs_autorec_reversal_je();
DROP TABLE IF EXISTS wbs_autorec_reversal;
ALTER TABLE journal_entry DROP CONSTRAINT IF EXISTS journal_entry_journal_type_check;
ALTER TABLE journal_entry ADD CONSTRAINT journal_entry_journal_type_check CHECK (journal_type IN ('MANUAL','AUTO','REVERSAL','RECLASS'));
ALTER TABLE wbs_autorec_execution_event DROP CONSTRAINT IF EXISTS wbs_autorec_execution_event_command_check;
ALTER TABLE wbs_autorec_execution_event DROP CONSTRAINT IF EXISTS wbs_autorec_execution_event_current_state_check;
ALTER TABLE wbs_autorec_execution_event DROP CONSTRAINT IF EXISTS wbs_autorec_execution_event_next_state_check;
ALTER TABLE wbs_autorec_execution_event DROP CONSTRAINT IF EXISTS wbs_autorec_execution_event_transition_check;
ALTER TABLE wbs_autorec_execution_event ADD CONSTRAINT wbs_autorec_execution_event_command_check CHECK(command IN ('RESERVE','RELEASE','INCUR'));
ALTER TABLE wbs_autorec_execution_event ADD CONSTRAINT wbs_autorec_execution_event_current_state_check CHECK(current_state IN ('REVIEW_REQUIRED','RESERVED','RELEASED'));
ALTER TABLE wbs_autorec_execution_event ADD CONSTRAINT wbs_autorec_execution_event_next_state_check CHECK(next_state IN ('RESERVED','RELEASED','INCURRED'));
ALTER TABLE wbs_autorec_execution_event ADD CONSTRAINT wbs_autorec_execution_event_transition_check CHECK((command='RESERVE' AND current_state='REVIEW_REQUIRED' AND next_state='RESERVED') OR (command='RELEASE' AND current_state='RESERVED' AND next_state='RELEASED') OR (command='INCUR' AND current_state='RELEASED' AND next_state='INCURRED'));
DELETE FROM permission_catalog WHERE permission_code IN ('BANK.AUTOREC.G11.REVERSE_DRAFT','BANK.AUTOREC.G11.REVERSE');
COMMIT;
